window.futvizVista("construir-vs-producir","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"construir-vs-producir\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"construir-vs-producir\"]={\"id\":\"construir-vs-producir\",\"titulo\":\"Construcci\u00f3n vs. producci\u00f3n\",\"bajada\":\"A la derecha, quien m\u00e1s construye (xG de construcci\u00f3n por 90'); arriba, quien m\u00e1s produce directo (xG + xA).\",\"pregunta\":\"\u00bfQui\u00e9n construye, qui\u00e9n termina y qui\u00e9n lo hace todo?\",\"tabla\":\"jugadores\",\"entidad\":\"jugadores\",\"x\":{\"col\":\"xgbuild90\",\"label\":\"xG de construcci\u00f3n por 90'\",\"corto\":\"Construcci\u00f3n\",\"dec\":2},\"y\":{\"col\":\"xga90\",\"label\":\"Producci\u00f3n esperada por 90' (xG + xA)\",\"corto\":\"Producci\u00f3n\",\"dec\":2},\"referencia\":{\"tipo\":\"promedios\",\"cuadrantes\":{\"tl\":\"Producen mucho sin construir\",\"tr\":\"Construyen y producen mucho\",\"bl\":\"Construyen y producen poco\",\"br\":\"Construyen mucho sin producir\"},\"cuantil\":0.8},\"requiere\":[\"xgbuild90\",\"xga90\"],\"subtitulo\":\"Jugadores con \u2265{min} min \u00b7 {temporada}\",\"filtros\":{\"posicion\":true,\"nivel\":true,\"sub21\":true},\"metricas\":[{\"id\":\"x\",\"etiqueta\":\"Construcci\u00f3n\",\"ayuda\":\"Ordenados por xG de construcci\u00f3n por 90'\"},{\"id\":\"y\",\"etiqueta\":\"Producci\u00f3n\",\"ayuda\":\"Ordenados por Producci\u00f3n esperada por 90' (xG + xA)\"}],\"queMirar\":\"Separa a quien arma las jugadas de tiro de quien las termina, por 90 minutos. La construcci\u00f3n, en el eje horizontal, es el xG de las jugadas de tiro en las que participa sin tirar ni dar el \u00faltimo pase. La producci\u00f3n, en el vertical, suma el xG de sus tiros y el xA de sus pases: lo que genera de forma directa. Las l\u00edneas marcan el 20% m\u00e1s alto de cada eje.\",\"insight\":\"construir\",\"fuente\":\"Understat\",\"colorPor\":[\"liga\"],\"posicionesIni\":[\"Defensa\",\"Medio\",\"Delantero\"]};</script>");